import { platform, versions } from 'node:process';
import config, { RUNTIME_CLI_VERSION } from '../../config.js';
import { detectPackageManager } from '../package-manager.js';
/**
 * Facts about the environment that runs a deploy.
 * Sent as the `client` part of deploy metadata. Keys with an `undefined` value drop out of the JSON body.
 */
export function getClientMetadata({ cliVersion, dir, }) {
    return {
        cliVersion,
        runtimeCliVersion: RUNTIME_CLI_VERSION,
        nodeVersion: versions.node,
        nodePackageManager: detectPackageManager(dir),
        platform,
        ci: config.isCi,
    };
}
